/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var DiscreteScale = require( '@stdlib/plot/vega/scale/discrete' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );
var TYPE = require( './type/type.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAlign = require( './align/get.js' );
var setAlign = require( './align/set.js' );

var getDomainImplicit = require( './domain-implicit/get.js' );
var setDomainImplicit = require( './domain-implicit/set.js' );

var getPadding = require( './padding/get.js' );
var setPadding = require( './padding/set.js' );

var getPaddingInner = require( './padding-inner/get.js' );
var setPaddingInner = require( './padding-inner/set.js' );

var getPaddingOuter = require( './padding-outer/get.js' );
var setPaddingOuter = require( './padding-outer/set.js' );

var getProperties = require( './properties/get.js' );

var getType = require( './type/get.js' );
var setType = require( './type/set.js' );


// VARIABLES //

var debug = logger( 'vega:band-scale:main' );


// MAIN //

/**
* Band scale constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.name - scale name
* @param {number} [options.align=0.5] - alignment of elements within the scale range.
* @param {(Collection|Object|Signal)} [options.domain] - domain of associated data values
* @param {boolean} [options.domainImplicit=false] - boolean flag indicating whether an ordinal domain should be implicitly extended with new values.
* @param {number} [options.domainMax] - maximum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMin] - minimum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMid] - single mid-point value inserted into a two-element domain
* @param {Collection} [options.domainRaw] - array of raw domain values which overrides the `domain` property
* @param {(string|Object)} [options.interpolate] - scale range interpolation method
* @param {number} [options.padding=0] - padding value which sets paddingInner and paddingOuter to the same padding value
* @param {number} [options.paddingInner=0] - inner padding within each band step (as a fraction of the step size)
* @param {number} [options.paddingOuter=0] - outer padding at the ends of the scale range (as a fraction of the step size)
* @param {(Collection|Object|Signal|string)} [options.range] - scale range
* @param {boolean} [options.reverse=false] - boolean indicating whether to reverse the order of the scale range
* @param {boolean} [options.round=false] - boolean indicating whether to round numeric output values to integers
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {BandScale} scale instance
*
* @example
* var scale = new BandScale({
*     'name': 'xScale'
* });
* // returns <BandScale>
*/
function BandScale( options ) {
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof BandScale ) ) {
		return new BandScale( options );
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	if ( hasProp( options, 'type' ) && options.type !== TYPE ) {
		throw new TypeError( format( 'invalid argument. `%s` option must be equal to "%s". Option: `%s`.', 'type', TYPE, options.type ) );
	}
	// Check for required properties...
	if ( !hasProp( options, 'name' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the scale name.' );
	}
	DiscreteScale.call( this, {
		'name': options.name,
		'type': TYPE
	});
	this._type = TYPE;

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;
}

/*
* Inherit from a parent prototype.
*/
inherit( BandScale, DiscreteScale );

/**
* Constructor name.
*
* @private
* @name name
* @memberof BandScale
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( BandScale, 'name', 'BandScale' );

/**
* Alignment of elements within the scale range.
*
* @name align
* @memberof BandScale.prototype
* @type {number}
* @default 0
*
* @example
* var scale = new BandScale({
*     'name': 'xScale',
*     'align': 0.5
* });
*
* var v = scale.align;
* // returns 0.5
*/
setReadWriteAccessor( BandScale.prototype, 'align', getAlign, setAlign );

/**
* Boolean flag indicating whether an ordinal domain should be implicitly extended with new values.
*
* @name domainImplicit
* @memberof BandScale.prototype
* @type {boolean}
* @default false
*
* @example
* var scale = new BandScale({
*     'name': 'xScale',
*     'domainImplicit': true
* });
*
* var v = scale.domainImplicit;
* // returns true
*/
setReadWriteAccessor( BandScale.prototype, 'domainImplicit', getDomainImplicit, setDomainImplicit );

/**
* Padding value which sets paddingInner and paddingOuter to the same padding value.
*
* @name padding
* @memberof BandScale.prototype
* @type {number}
* @default 0.5
*
* @example
* var scale = new BandScale({
*     'name': 'xScale',
*     'padding': 1
* });
*
* var v = scale.padding;
* // returns 1
*/
setReadWriteAccessor( BandScale.prototype, 'padding', getPadding, setPadding );

/**
* Inner padding within each band step (as a fraction of the step size).
*
* @name paddingInner
* @memberof BandScale.prototype
* @type {number}
* @default 0
*
* @example
* var scale = new BandScale({
*     'name': 'xScale',
*     'paddingInner': 0.5
* });
*
* var v = scale.paddingInner;
* // returns 0.5
*/
setReadWriteAccessor( BandScale.prototype, 'paddingInner', getPaddingInner, setPaddingInner );

/**
* Outer padding at the ends of the scale range (as a fraction of the step size).
*
* @name paddingOuter
* @memberof BandScale.prototype
* @type {number}
* @default 0
*
* @example
* var scale = new BandScale({
*     'name': 'xScale',
*     'paddingOuter': 0.5
* });
*
* var v = scale.paddingOuter;
* // returns 0.5
*/
setReadWriteAccessor( BandScale.prototype, 'paddingOuter', getPaddingOuter, setPaddingOuter );

/**
* Scale properties.
*
* @name properties
* @memberof BandScale.prototype
* @type {Array<string>}
*
* @example
* var scale = new BandScale({
*     'name': 'xScale'
* });
*
* var v = scale.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( BandScale.prototype, 'properties', getProperties );

/**
* Scale type.
*
* @name type
* @memberof BandScale.prototype
* @type {string}
* @default 'band'
*
* @example
* var scale = new BandScale({
*     'name': 'xScale'
* });
*
* var v = scale.type;
* // returns 'band'
*/
setReadWriteAccessor( BandScale.prototype, 'type', getType, setType );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof BandScale.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var scale = new BandScale({
*     'name': 'xScale'
* });
*
* var v = scale.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( BandScale.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = BandScale;
